from audit_tools import *
p=ROOT/'records/scan332.py'
r=ast.literal_eval(p.read_text())
r['note']=r['note'].replace('No equality between these incomplete lines is asserted by this transcription.','The vertical parallel strokes express intended equalities, although the different scalar powers remain unreconciled in the unfinished calculation.')
p.write_text(pprint.pformat(r,sort_dicts=False,width=120)+'\n')
cc=[change(place,"two apostrophes",'vertical equality signs described in note',r'\Vert',evidence,'misread symbol or index',True,False,'high','page','no',True) for place,evidence in [('between composition and alpha formula','Two short parallel upright strokes stand between corresponding formulas, with no enclosing quoted words.'),('below underlined u_* formula','Two parallel strokes sit vertically between the underlined formula and the scalar expression.'),('before right-margin scalar formula','The pair is above the right-hand expression and parallel to the other vertical equality signs on the sheet.')]]
finish(332,replacements=[(r"\[\text{''}\]",r'\[\Vert\]',2),(r"\margin{$\text{''}\quad u(\lambda)^{q}\alpha_{pq}\,u(x)^{pq}$}",r'\margin{$\begin{gathered}\Vert\\u(\lambda)^{q}\alpha_{pq}\,u(x)^{pq}\end{gathered}$}')],changes=cc,note='Reread both halves line by line. Three pairs previously set as apostrophes are vertical equality signs: the composition-to-alpha comparison and the two lower scalar comparisons. Their parallel upright strokes and placement agree with the vertical equalities confirmed on later pages. The factorial under alpha was already set correctly as a vertical equality. All anomalous parentheses, the isolated deleted1, the cancelled u_p and the unequal scalar exponents remain. No new crop was needed.',extra_hand=['Second reading: the three pairs of upright ticks between formulas are vertical equalities, not quotation marks. This holds at all four such pairs on332 including the already-correct coefficient relation; C misread three as apostrophes, while H described the lower equalities.'],extra_notation=[('Vert','Four vertical equality pairs; three corrected from quotation marks in the second reading.')])
